/**
 * @name Violet Night EN
 * @description Blue-violet theme: anime girls in the corners, falling leaves, stars and shooting stars in the background
 * @author your-name
 * @version 3.0.0
 */

/* ============ SETTINGS ============ */
:root {
  /* Images. Replace with your own: url("https://...") */
  --vn-girl-corner: url("data:image/png;base64,");   /* дівчина в правому нижньому куті (поверх) */
  --vn-girl-back:   url("data:image/png;base64,");   /* дівчина на задньому плані */
  --vn-scene:       url("data:image/jpeg;base64,");   /* запасна картинка зі сценою */
  --vn-girl-extra:  url("data:image/png;base64,");   /* запасна картинка */

  --vn-accent: #8f7bff;
  --vn-accent-2: #5aa2ff;
  --vn-text: #ece8ff;
  --vn-muted: #a69fd6;

  /* 0 = off */
  --vn-leaves-opacity: 0.5;
  --vn-stars-opacity: 0.7;
  --vn-branch-opacity: 0.8;
  --vn-corner-opacity: 0.6;
  --vn-back-opacity: 0.8;

  /* Corner girl size */
  --vn-girl-w: clamp(195px, 17vw, 330px);
  --vn-girl-h: clamp(230px, 35vh, 390px);

  /* What she says (one after another, ~10 s each). Put your own text in quotes. */
  --vn-say-1: "Hi there! 💜";
  --vn-say-2: "Don't forget to drink some water 💧";
  --vn-say-3: "Go play, I'll wait here 🎮";
  --vn-say-4: "You're doing great today ✨";
  --vn-say-5: "Maybe take a short break? 🌙";
  --vn-say-6: "GG, don't tilt ⭐";
  --vn-bubble-opacity: 1;      /* 0 = hide the bubble */
  --vn-shoot-opacity: 0.9;     /* 0 = turn off shooting stars */
}

/* ============ DISCORD COLORS ============ */
:root, .theme-dark, .theme-darker, .theme-midnight, .theme-light {
  --brand-experiment: var(--vn-accent);
  --brand-500: var(--vn-accent);
  --brand-560: #7a66f0;
  --brand-600: #6a56e0;
  --brand-experiment-560: #7a66f0;
  --brand-experiment-600: #6a56e0;
  --text-link: var(--vn-accent-2);
  --text-normal: var(--vn-text);
  --text-default: var(--vn-text);
  --header-primary: #ffffff;
  --header-secondary: var(--vn-muted);
  --text-muted: var(--vn-muted);
  --interactive-normal: #b9b3e6;
  --interactive-hover: #ffffff;
  --interactive-active: #ffffff;
  --channels-default: #a69fd6;
  --scrollbar-thin-thumb: #4a3fa0;
  --scrollbar-auto-thumb: #4a3fa0;
  --scrollbar-auto-track: transparent;

  --background-primary: rgba(18, 15, 46, 0.62);
  --background-secondary: rgba(14, 12, 38, 0.68);
  --background-secondary-alt: rgba(11, 9, 30, 0.72);
  --background-tertiary: rgba(8, 7, 24, 0.76);
  --background-floating: rgba(16, 13, 42, 0.96);
  --background-accent: rgba(60, 48, 140, 0.8);
  --background-modifier-hover: rgba(143, 123, 255, 0.12);
  --background-modifier-selected: rgba(143, 123, 255, 0.22);
  --background-modifier-active: rgba(143, 123, 255, 0.18);
  --background-modifier-accent: rgba(143, 123, 255, 0.16);
  --chat-background: transparent;
  --chat-background-default: transparent;
  --channeltextarea-background: rgba(30, 24, 74, 0.7);

  --background-base-lowest: rgba(8, 7, 24, 0.7);
  --background-base-lower: rgba(11, 9, 30, 0.66);
  --background-base-low: rgba(14, 12, 38, 0.62);
  --background-surface-high: rgba(22, 18, 56, 0.66);
  --background-surface-higher: rgba(28, 23, 70, 0.78);
  --background-surface-highest: rgba(34, 28, 84, 0.86);
  --bg-overlay-1: rgba(14, 12, 38, 0.62);
  --bg-overlay-2: rgba(18, 15, 46, 0.58);
  --bg-overlay-3: rgba(11, 9, 30, 0.66);
  --bg-overlay-chat: transparent;
}

/* ============ BACKGROUND (gradient on html, everything else transparent) ============ */
html {
  background-color: #0b0920 !important;
  background-image:
    radial-gradient(ellipse at 15% 0%, rgba(90, 162, 255, 0.28), transparent 55%),
    radial-gradient(ellipse at 85% 100%, rgba(143, 123, 255, 0.35), transparent 55%),
    linear-gradient(160deg, #0b0920 0%, #1a1245 55%, #0e1a4d 100%) !important;
  background-attachment: fixed !important;
}
body,
#app-mount,
[class*="app__"],
[class*="bg__"],
[class*="layers__"] {
  background: transparent !important;
}

/* ============ BACKGROUND LAYERS: everything below sits BEHIND the interface ============ */

/* All animations here only move transform / opacity, which the GPU handles,
   so the CPU is barely used. Background images are NOT repainted. */

/* leaves (one layer, slowly falling) */
html::before {
  content: "";
  position: fixed;
  top: -1000px;
  left: -420px;
  width: calc(100% + 420px);
  height: calc(100% + 1000px);
  z-index: -1;
  pointer-events: none;
  opacity: var(--vn-leaves-opacity);
  background-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='420' height='1000'><g transform='translate(70 90) rotate(20) scale(1)' fill='%238f7bff'><path d='M0 -14C11 -10 13 6 0 17C-13 6 -11 -10 0 -14Z'/><path d='M0 -12V16' stroke='%231b1646' stroke-width='1' opacity='.5'/></g><g transform='translate(320 480) rotate(-40) scale(1.2)' fill='%235aa2ff'><path d='M0 -14C11 -10 13 6 0 17C-13 6 -11 -10 0 -14Z'/><path d='M0 -12V16' stroke='%231b1646' stroke-width='1' opacity='.5'/></g><g transform='translate(160 820) rotate(60) scale(1)' fill='%23b9a6ff'><path d='M0 -14C11 -10 13 6 0 17C-13 6 -11 -10 0 -14Z'/><path d='M0 -12V16' stroke='%231b1646' stroke-width='1' opacity='.5'/></g></svg>");
  background-size: 420px 1000px;
  background-repeat: repeat;
  will-change: transform;
  animation: vn-leaves 80s linear infinite;
}

/* stars (one layer, slowly falling + soft twinkle) */
html::after {
  content: "";
  position: fixed;
  top: -900px;
  left: -420px;
  width: calc(100% + 420px);
  height: calc(100% + 900px);
  z-index: -1;
  pointer-events: none;
  opacity: var(--vn-stars-opacity);
  background-image: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' width='420' height='900'><path transform='translate(60 60) scale(0.8)' fill='%23ffffff' d='M0 -10C1 -3 3 -1 10 0C3 1 1 3 0 10C-1 3 -3 1 -10 0C-3 -1 -1 -3 0 -10Z'/><path transform='translate(300 250) scale(0.6)' fill='%23bfb2ff' d='M0 -10C1 -3 3 -1 10 0C3 1 1 3 0 10C-1 3 -3 1 -10 0C-3 -1 -1 -3 0 -10Z'/><path transform='translate(150 500) scale(0.7)' fill='%239fd2ff' d='M0 -10C1 -3 3 -1 10 0C3 1 1 3 0 10C-1 3 -3 1 -10 0C-3 -1 -1 -3 0 -10Z'/><path transform='translate(350 720) scale(0.8)' fill='%23ffffff' d='M0 -10C1 -3 3 -1 10 0C3 1 1 3 0 10C-1 3 -3 1 -10 0C-3 -1 -1 -3 0 -10Z'/><path transform='translate(40 820) scale(0.5)' fill='%23d6ccff' d='M0 -10C1 -3 3 -1 10 0C3 1 1 3 0 10C-1 3 -3 1 -10 0C-3 -1 -1 -3 0 -10Z'/><circle cx='200' cy='130' r='1.4' fill='%23fff'/><circle cx='360' cy='390' r='1.2' fill='%23cfc6ff'/><circle cx='90' cy='330' r='1.3' fill='%23fff'/><circle cx='250' cy='640' r='1.3' fill='%239fd2ff'/><circle cx='120' cy='700' r='1.2' fill='%23fff'/></svg>");
  background-size: 420px 900px;
  background-repeat: repeat;
  will-change: transform, opacity;
  animation: vn-stars 140s linear infinite, vn-twinkle 7s ease-in-out infinite;
}

/* background girl (static) */
body::before {
  content: "";
  position: fixed;
  left: 24vw;
  bottom: 0;
  width: 28vw;
  height: 62vh;
  z-index: -1;
  pointer-events: none;
  opacity: var(--vn-back-opacity);
  background: var(--vn-girl-back) no-repeat center bottom / contain;
}

/* branch at the top (sways very slightly) */
body::after {
  content: "";
  position: fixed;
  left: 0;
  top: 0;
  width: 100%;
  height: 90px;
  z-index: -1;
  pointer-events: none;
  opacity: var(--vn-branch-opacity);
  background: url("data:image/svg+xml;utf8,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 1200 110' preserveAspectRatio='none'><path d='M-20 22C150 38 260 12 420 40S700 48 860 26S1100 12 1220 36' fill='none' stroke='%233a2c88' stroke-width='9' stroke-linecap='round'/><path d='M300 32C318 60 312 80 330 98M640 44C655 66 685 72 692 92M960 26C978 52 1005 58 1018 78M130 28C122 52 104 62 98 80' fill='none' stroke='%233a2c88' stroke-width='4' stroke-linecap='round'/><g transform='translate(330 98) rotate(20) scale(1)' fill='%238f7bff'><path d='M0 -14C11 -10 13 6 0 17C-13 6 -11 -10 0 -14Z'/><path d='M0 -12V16' stroke='%231b1646' stroke-width='1' opacity='.5'/></g><g transform='translate(692 92) rotate(-30) scale(1.1)' fill='%235aa2ff'><path d='M0 -14C11 -10 13 6 0 17C-13 6 -11 -10 0 -14Z'/><path d='M0 -12V16' stroke='%231b1646' stroke-width='1' opacity='.5'/></g><g transform='translate(1018 78) rotate(40) scale(1)' fill='%23b9a6ff'><path d='M0 -14C11 -10 13 6 0 17C-13 6 -11 -10 0 -14Z'/><path d='M0 -12V16' stroke='%231b1646' stroke-width='1' opacity='.5'/></g><g transform='translate(98 80) rotate(-20) scale(0.9)' fill='%236fd0ff'><path d='M0 -14C11 -10 13 6 0 17C-13 6 -11 -10 0 -14Z'/><path d='M0 -12V16' stroke='%231b1646' stroke-width='1' opacity='.5'/></g><g transform='translate(420 52) rotate(60) scale(0.9)' fill='%237d6bff'><path d='M0 -14C11 -10 13 6 0 17C-13 6 -11 -10 0 -14Z'/><path d='M0 -12V16' stroke='%231b1646' stroke-width='1' opacity='.5'/></g><g transform='translate(560 52) rotate(-50) scale(0.9)' fill='%23a58cff'><path d='M0 -14C11 -10 13 6 0 17C-13 6 -11 -10 0 -14Z'/><path d='M0 -12V16' stroke='%231b1646' stroke-width='1' opacity='.5'/></g><g transform='translate(860 40) rotate(30) scale(0.9)' fill='%236fd0ff'><path d='M0 -14C11 -10 13 6 0 17C-13 6 -11 -10 0 -14Z'/><path d='M0 -12V16' stroke='%231b1646' stroke-width='1' opacity='.5'/></g><g transform='translate(1150 44) rotate(-40) scale(0.9)' fill='%238f7bff'><path d='M0 -14C11 -10 13 6 0 17C-13 6 -11 -10 0 -14Z'/><path d='M0 -12V16' stroke='%231b1646' stroke-width='1' opacity='.5'/></g></svg>") no-repeat top center / 100% 100%;
  transform-origin: 50% 0;
  will-change: transform;
  animation: vn-sway 10s ease-in-out infinite;
}

@keyframes vn-leaves {
  from { transform: translate3d(0, 0, 0); }
  to   { transform: translate3d(420px, 1000px, 0); }
}
@keyframes vn-stars {
  from { transform: translate3d(0, 0, 0); }
  to   { transform: translate3d(420px, 900px, 0); }
}
@keyframes vn-twinkle {
  0%, 100% { opacity: var(--vn-stars-opacity); }
  50% { opacity: calc(var(--vn-stars-opacity) * 0.55); }
}
@keyframes vn-sway {
  0%, 100% { transform: rotate(-0.35deg); }
  50% { transform: rotate(0.35deg); }
}
@keyframes vn-float {
  0%, 100% { transform: translate3d(0, 0, 0); }
  50% { transform: translate3d(0, -7px, 0); }
}

/* ============ CORNER GIRL (on top, never blocks clicks, gently "breathes") ============ */
#app-mount::after {
  content: "";
  position: fixed;
  right: 0;
  bottom: 0;
  width: var(--vn-girl-w);
  height: var(--vn-girl-h);
  z-index: 9;
  pointer-events: none;
  opacity: var(--vn-corner-opacity);
  background: var(--vn-girl-corner) no-repeat right bottom / contain;
  will-change: transform;
  animation: vn-float 8s ease-in-out infinite;
}
/* speech bubble above the girl */
#app-mount::before {
  content: var(--vn-say-1);
  position: fixed;
  right: 16px;
  bottom: calc(var(--vn-girl-h) - 26px);
  max-width: 190px;
  padding: 6px 10px;
  z-index: 10;
  pointer-events: none;
  font: 600 11px/1.3 "gg sans", "Segoe UI", sans-serif;
  color: #fff;
  background: rgba(34, 27, 88, 0.92);
  border: 1px solid rgba(143, 123, 255, 0.55);
  border-radius: 12px 12px 4px 12px;
  opacity: 0;
  transform-origin: 100% 100%;
  will-change: transform, opacity;
  animation: vn-say 60s linear infinite;
}
@keyframes vn-say {
  0.000% { content: var(--vn-say-1); opacity: 0; transform: translate3d(0, 6px, 0) scale(0.85); }
  1.500% { content: var(--vn-say-1); opacity: var(--vn-bubble-opacity); transform: translate3d(0, 0, 0) scale(1); }
  14.667% { content: var(--vn-say-1); opacity: var(--vn-bubble-opacity); transform: translate3d(0, 0, 0) scale(1); }
  16.167% { content: var(--vn-say-1); opacity: 0; transform: translate3d(0, -3px, 0) scale(0.95); }
  16.667% { content: var(--vn-say-2); opacity: 0; transform: translate3d(0, 6px, 0) scale(0.85); }
  18.167% { content: var(--vn-say-2); opacity: var(--vn-bubble-opacity); transform: translate3d(0, 0, 0) scale(1); }
  31.333% { content: var(--vn-say-2); opacity: var(--vn-bubble-opacity); transform: translate3d(0, 0, 0) scale(1); }
  32.833% { content: var(--vn-say-2); opacity: 0; transform: translate3d(0, -3px, 0) scale(0.95); }
  33.333% { content: var(--vn-say-3); opacity: 0; transform: translate3d(0, 6px, 0) scale(0.85); }
  34.833% { content: var(--vn-say-3); opacity: var(--vn-bubble-opacity); transform: translate3d(0, 0, 0) scale(1); }
  48.000% { content: var(--vn-say-3); opacity: var(--vn-bubble-opacity); transform: translate3d(0, 0, 0) scale(1); }
  49.500% { content: var(--vn-say-3); opacity: 0; transform: translate3d(0, -3px, 0) scale(0.95); }
  50.000% { content: var(--vn-say-4); opacity: 0; transform: translate3d(0, 6px, 0) scale(0.85); }
  51.500% { content: var(--vn-say-4); opacity: var(--vn-bubble-opacity); transform: translate3d(0, 0, 0) scale(1); }
  64.667% { content: var(--vn-say-4); opacity: var(--vn-bubble-opacity); transform: translate3d(0, 0, 0) scale(1); }
  66.167% { content: var(--vn-say-4); opacity: 0; transform: translate3d(0, -3px, 0) scale(0.95); }
  66.667% { content: var(--vn-say-5); opacity: 0; transform: translate3d(0, 6px, 0) scale(0.85); }
  68.167% { content: var(--vn-say-5); opacity: var(--vn-bubble-opacity); transform: translate3d(0, 0, 0) scale(1); }
  81.333% { content: var(--vn-say-5); opacity: var(--vn-bubble-opacity); transform: translate3d(0, 0, 0) scale(1); }
  82.833% { content: var(--vn-say-5); opacity: 0; transform: translate3d(0, -3px, 0) scale(0.95); }
  83.333% { content: var(--vn-say-6); opacity: 0; transform: translate3d(0, 6px, 0) scale(0.85); }
  84.833% { content: var(--vn-say-6); opacity: var(--vn-bubble-opacity); transform: translate3d(0, 0, 0) scale(1); }
  98.000% { content: var(--vn-say-6); opacity: var(--vn-bubble-opacity); transform: translate3d(0, 0, 0) scale(1); }
  99.500% { content: var(--vn-say-6); opacity: 0; transform: translate3d(0, -3px, 0) scale(0.95); }
  100% { content: var(--vn-say-6); opacity: 0; }
}

@media (max-width: 1100px) {
  #app-mount::before, #app-mount::after, body::before { display: none; }
}

@media (prefers-reduced-motion: reduce) {
  html::before, html::after, body::after, #app-mount::after { animation: none; will-change: auto; }
  #app-mount::before { animation: none; opacity: 0; }
  [class*="numberBadge"] { animation: none; }
  [class*="app__"]::before, [class*="app__"]::after { animation: none; opacity: 0; }
  [class*="scrollerInner"] > li[class*="messageListItem"]:last-of-type { transition: none; }
  [class*="privateChannels"] li[class*="channel"], [class*="peopleListItem"], li[class*="containerDefault"] { transition: none; }
}

/* ============ UI ANIMATIONS (transform / opacity only, short) ============ */

/* hovering a DM, friend or channel makes it grow slightly */
[class*="privateChannels"] li[class*="channel"],
[class*="peopleListItem"],
li[class*="containerDefault"] {
  transform-origin: 0 50%;
  transition: transform 0.18s cubic-bezier(0.2, 0.8, 0.2, 1);
}
[class*="privateChannels"] li[class*="channel"]:hover,
[class*="peopleListItem"]:hover,
li[class*="containerDefault"]:hover {
  transform: translate3d(3px, 0, 0) scale(1.025);
}

/* new message: light fade-in via transition (runs ONCE when the element appears,
   not restarted on re-render, only opacity + transform) */
[class*="scrollerInner"] > li[class*="messageListItem"]:last-of-type {
  transition: opacity 0.22s ease-out, transform 0.22s ease-out;
}
@starting-style {
  [class*="scrollerInner"] > li[class*="messageListItem"]:last-of-type {
    opacity: 0;
    transform: translate3d(0, 8px, 0);
  }
}

/* message box softly glows while you type */
[class*="channelTextArea"] {
  transition: box-shadow 0.25s ease, border-color 0.25s ease;
}
[class*="channelTextArea"]:focus-within {
  border-color: rgba(143, 123, 255, 0.75);
  box-shadow: 0 0 22px rgba(143, 123, 255, 0.35);
}

/* red unread badges gently "breathe" */
[class*="numberBadge"] {
  animation: vn-pulse 2.6s ease-in-out infinite;
}
@keyframes vn-pulse {
  0%, 100% { transform: scale(1); }
  50% { transform: scale(1.12); }
}

/* shooting stars: every so often a short streak flies across the screen */
[class*="app__"]::before,
[class*="app__"]::after {
  content: "";
  position: fixed;
  top: 0;
  left: 72vw;
  width: 150px;
  height: 2px;
  z-index: -1;
  pointer-events: none;
  opacity: 0;
  border-radius: 2px;
  background: linear-gradient(90deg, #ffffff, rgba(190, 175, 255, 0.6) 40%, transparent);
  transform-origin: 0 50%;
  will-change: transform, opacity;
  animation: vn-shoot 26s linear infinite;
}
[class*="app__"]::after {
  left: 94vw;
  top: 24vh;
  width: 110px;
  animation-delay: -13s;
}
@keyframes vn-shoot {
  0%   { opacity: 0; transform: rotate(-35deg) translate3d(0, 0, 0); }
  1%   { opacity: var(--vn-shoot-opacity); }
  5%   { opacity: 0; transform: rotate(-35deg) translate3d(-900px, 0, 0); }
  100% { opacity: 0; transform: rotate(-35deg) translate3d(-900px, 0, 0); }
}

/* ============ DETAILS ============ */
::selection { background: rgba(143, 123, 255, 0.45); color: #fff; }

[class*="lookFilled"][class*="colorBrand"] {
  background: linear-gradient(135deg, #7a66f0, #4f8cff) !important;
  border: none !important;
}

[class*="channelTextArea"] {
  border: 1px solid rgba(143, 123, 255, 0.25);
  box-shadow: 0 0 18px rgba(90, 162, 255, 0.12);
  border-radius: 10px;
}

::-webkit-scrollbar { width: 8px; height: 8px; }
::-webkit-scrollbar-thumb { background: #4a3fa0; border-radius: 8px; }
::-webkit-scrollbar-track { background: transparent; }
